# 12-TET frequencies + ADSR envelope (public-domain music math)
def note_freq(midi):
    return 440.0 * 2 ** ((midi - 69) / 12)

for name, m in [("A4", 69), ("C4", 60), ("C5", 72)]:
    print(f"{name} (MIDI {m}): {note_freq(m):.2f} Hz")

def adsr(t, a=0.01, d=0.1, s=0.7, r=0.2, note_len=0.5):
    if t < a: return t / a
    t -= a
    if t < d: return 1 - (1 - s) * t / d
    t -= d
    if t < note_len: return s
    t -= note_len
    return max(0.0, s * (1 - t / r))

env = [round(adsr(i/20), 2) for i in range(16)]
print("\nADSR shape (20 steps/s):", env)
